        erow = eligible_df.iloc[-1].reindex(cols)
        elig = erow.fillna(False).astype(bool)
    else:
        elig = pd.Series(True, index=cols)

    last_price = prices.iloc[-1]
    df = pd.DataFrame({
        'prox': prox,
        'resmom': resmom,
        'vol': vol60,
        'adv': adv,
        'eligible': elig,
        'last': last_price,
    })
    df = df.replace([np.inf, -np.inf], np.nan)
    df = df[df['eligible'] & df['last'].notna() & df['prox'].notna() & df['resmom'].notna() & df['vol'].notna() & (df['vol'] > 0)]

    if len(df) < 4:
        return pd.Series(0.0, index=universe)

    if df['adv'].notna().sum() >= 5:
        df = df[df['adv'].notna() & (df['adv'] > 0)]
        if len(df) >= 5:
            q = df['adv'].quantile(0.20)
            df = df[df['adv'] >= q]

    if len(df) < 4:
        return pd.Series(0.0, index=universe)

    rank_prox = df['prox'].rank(method='average', pct=True)
    rank_resmom = df['resmom'].rank(method='average', pct=True)
    rank_lowvol = (-df['vol']).rank(method='average', pct=True)
    df['score'] = 0.45 * rank_prox + 0.40 * rank_resmom + 0.15 * rank_lowvol

    n_side = min(50, len(df) // 2)
    if n_side < 1:
        return pd.Series(0.0, index=universe)

    ordered = df.sort_values('score', ascending=False)
    longs = ordered.index[:n_side]
    shorts = ordered.index[-n_side:]

    side_gross = min(0.5, 0.02 * n_side)
    mkt_level = (1.0 + mkt.fillna(0.0)).cumprod()
    if len(mkt_level) >= 200:
        ma = mkt_level.tail(200).mean()
        if mkt_level.iloc[-1] < ma:
            side_gross *= 0.5
    w = side_gross / n_side

    weights = pd.Series(0.0, index=universe)
    weights.loc[longs] = w
    weights.loc[shorts] = -w
    weights = weights.replace([np.inf, -np.inf], 0.0).fillna(0.0).clip(-0.02, 0.02)
    return weights.astype(float)

import numpy as np
import pandas as pd

def generate_weights(history, universe):
    tickers = pd.Index(list(universe))
    n = len(tickers)
    if n == 0:
        return pd.Series(dtype=float)
    zero = pd.Series(np.zeros(n, dtype=float), index=tickers)
    ac = history.get('adjusted_close')
    if ac is None or len(ac.index) < 5:
        return zero
    try:
        ac = ac.reindex(columns=tickers)
    except Exception:
        return zero
    dates = ac.index
    last_pos = len(dates) - 1
    signal_pos = last_pos
    if isinstance(dates, pd.DatetimeIndex) and last_pos >= 0:
        wd = dates.weekday.values
        mons = np.where(wd[:last_pos + 1] == 0)[0]
        if len(mons) > 0:
            signal_pos = mons[-1]
    L = 21
    if signal_pos < L + 1:
        return zero
    close_all = ac.values
    cur_close = close_all[last_pos]
    valid = np.isfinite(cur_close) & (cur_close > 1.0)
    elig = history.get('eligible')
    if elig is not None:
        try:
            e = elig.reindex(index=dates, columns=tickers)
            le = e.iloc[last_pos].values
            if le.dtype == bool:
                valid_e = le
            else:
                valid_e = np.array([(x is True) or (x == 1) for x in le], dtype=bool)
            if np.any(pd.notna(le)):
                valid &= valid_e
        except Exception:
            pass
    close_sig = close_all[:signal_pos + 1]
    ret = close_sig[-1] / close_sig[-1 - L] - 1.0
    valid &= np.isfinite(ret)
    vol = history.get('volume')
    if vol is not None:
        try:
            v = vol.reindex(index=dates, columns=tickers).values[:signal_pos + 1]
            if v.shape[0] >= 20:
                dv = np.nanmean(close_sig[-20:] * v[-20:], axis=0)
                valid &= np.isfinite(dv) & (dv > 0)
                if valid.sum() >= 20:
                    thresh = np.nanpercentile(dv[valid], 20)
                    valid &= dv >= thresh
        except Exception:
            pass
    idx = np.where(valid)[0]
    if len(idx) < 6:
        return zero
    raw_score = -ret[idx]
    scores = raw_score.copy()
    try:
        if close_sig.shape[0] >= 22:
            daily = close_sig[-21:] / close_sig[-22:-1] - 1.0
            vol20 = np.nanstd(daily, axis=0)
            vol20 = np.where(np.isfinite(vol20) & (vol20 > 1e-8), vol20, np.nan)
            adj = raw_score / vol20[idx]
            ok = np.isfinite(adj)
            scores = np.where(ok, adj, raw_score)
    except Exception:
        scores = raw_score
    order = np.argsort(scores)
    m = min(25, len(idx) // 2)
    if m < 1:
        return zero
    long_sel = idx[order[-m:]]
    short_sel = idx[order[:m]]
    wt = min(0.02, 0.5 / m)
    w = np.zeros(n, dtype=float)
    w[long_sel] = wt
    w[short_sel] = -wt
    w = np.nan_to_num(w, nan=0.0, posinf=0.0, neginf=0.0)
    w = np.clip(w, -0.02, 0.02)
    return pd.Series(w, index=tickers)

import numpy as np
import pandas as pd
import math

def _pct_rank(x):
    x = np.asarray(x, dtype=float)
    n = x.size
    if n == 0:
        return x
    if n == 1:
        return np.zeros(1, dtype=float)
    order = np.argsort(x, kind='mergesort')
    xs = x[order]
    ranks = np.empty(n, dtype=float)
    i = 0
    while i < n:
        j = i + 1
        while j < n and xs[j] == xs[i]:
            j += 1
        avg = (i + j - 1) / 2.0
        ranks[order[i:j]] = avg
        i = j
    return ranks / (n - 1.0) - 0.5

def _to_bool_array(v):
    n = len(v)
    out = np.zeros(n, dtype=bool)
    for i, x in enumerate(v):
        try:
            if pd.isna(x):
                continue
        except Exception:
            pass
        if isinstance(x, (bool, np.bool_)):
            out[i] = bool(x)
        else:
            try:
                out[i] = (float(x) != 0.0)
            except Exception:
                try:
                    out[i] = bool(x)
                except Exception:
                    out[i] = False
    return out

def _mom_from_close(close_sig, lookback, skip):
    if close_sig.shape[0] <= lookback + skip:
        return None
    num = close_sig[-1 - skip]
    den = close_sig[-1 - lookback]
    with np.errstate(divide='ignore', invalid='ignore'):
        r = num / den - 1.0
    return r

def generate_weights(history, universe):
    tickers = pd.Index(list(universe))
    n = len(tickers)
    if n == 0:
        return pd.Series(dtype=float)
    zero = pd.Series(np.zeros(n, dtype=float), index=tickers)
    ac_full = history.get('adjusted_close')
    if ac_full is None or len(ac_full.index) == 0:
        return zero
    total = len(ac_full.index)
    start = max(0, total - 420)
    try:
        ac = ac_full.iloc[start:].reindex(columns=tickers)
    except Exception:
        return zero
    dates = ac.index
    mrows = len(dates)
    if mrows < 70:
        return zero
    last_pos = mrows - 1
    try:
        months = dates.month.values
    except Exception:
        months = np.array([d.month for d in dates])
    month_starts = [i for i in range(1, mrows) if months[i] != months[i-1]]
    if len(month_starts) == 0:
        return zero
    signal_pos = month_starts[-1]
    if signal_pos < 60:
        return zero
    close_all = ac.values.astype(float)
    last_close = close_all[last_pos]
    valid = np.isfinite(last_close) & (last_close > 1.0)
    elig = history.get('eligible')
    if elig is not None:
        try:
            e = elig.iloc[start:].reindex(columns=tickers, index=dates)
            le = e.iloc[last_pos].values
            if len(le) > 0 and not pd.isna(le).all():
                valid &= _to_bool_array(le)
        except Exception:
            pass
    vol_field = history.get('volume')
    if vol_field is not None:
        try:
            v = vol_field.iloc[start:].reindex(columns=tickers, index=dates).values.astype(float)
            Lq = min(60, last_pos + 1)
            if Lq >= 20:
                cwin = close_all[last_pos - Lq + 1:last_pos + 1]
                vwin = v[last_pos - Lq + 1:last_pos + 1]
                dv = np.nanmean(cwin * vwin, axis=0)
                valid &= np.isfinite(dv) & (dv > 0)
                if valid.sum() >= 40:
                    thresh = np.nanpercentile(dv[valid], 30)
                    valid &= dv >= thresh
        except Exception:
            pass
    close_sig = close_all[:signal_pos + 1]
    if close_sig.shape[0] < 60:
        return zero
    ret = np.full(n, np.nan, dtype=float)
    r = _mom_from_close(close_sig, 252, 21)
    if r is not None:
        ret = r
    r = _mom_from_close(close_sig, 126, 10)
    if r is not None:
        ret = np.where(np.isfinite(ret), ret, r)
    r = _mom_from_close(close_sig, 63, 5)
    if r is not None:
        ret = np.where(np.isfinite(ret), ret, r)
    with np.errstate(divide='ignore', invalid='ignore'):
        returns = close_sig[1:] / close_sig[:-1] - 1.0
    if returns.shape[0] >= 20:
        vwin = returns[-126:] if returns.shape[0] >= 126 else returns
        stock_vol = np.nanstd(vwin, axis=0)
    else:
        stock_vol = np.full(n, np.nan, dtype=float)
    hwin = close_sig[-252:] if close_sig.shape[0] >= 252 else close_sig
    with np.errstate(invalid='ignore'):
        max_close = np.nanmax(hwin, axis=0)
        high_prox = close_sig[-1] / max_close - 1.0
        high_prox = np.where(np.isfinite(max_close) & (max_close > 0), high_prox, np.nan)
    twin = close_sig[-200:] if close_sig.shape[0] >= 200 else close_sig
    with np.errstate(invalid='ignore'):
        sma = np.nanmean(twin, axis=0)
        trend = close_sig[-1] / sma - 1.0
        trend = np.where(np.isfinite(sma) & (sma > 0), trend, np.nan)
    valid &= np.isfinite(ret) & np.isfinite(stock_vol) & (stock_vol > 1e-6) & np.isfinite(high_prox) & np.isfinite(trend)
    idx = np.where(valid)[0]
    if len(idx) < 10:
        return zero
    mom = ret[idx]
    volv = stock_vol[idx]
    hp = high_prox[idx]
    tr = trend[idx]
    with np.errstate(divide='ignore', invalid='ignore'):
        risk_adj = mom / np.maximum(volv, 1e-4)
    risk_adj = np.nan_to_num(risk_adj, nan=0.0, posinf=0.0, neginf=0.0)
    z_mom = _pct_rank(risk_adj)
    z_high = _pct_rank(hp)
    z_trend = _pct_rank(tr)
    z_lowvol = _pct_rank(-volv)
    if returns.shape[0] >= 60:
        rwin = returns[-200:] if returns.shape[0] >= 200 else returns
        market_ret = np.nanmean(rwin, axis=1)
        market_ret = np.nan_to_num(market_ret, nan=0.0, posinf=0.0, neginf=0.0)
        level = np.cumprod(1.0 + market_ret)
        base = np.nanmean(level[-200:]) if len(level) >= 200 else np.nanmean(level)
        if np.isfinite(base) and base > 0:
            mtrend = level[-1] / base - 1.0
        else:
            mtrend = 0.0
        mvol = np.nanstd(market_ret[-60:]) * math.sqrt(252.0)
        if not np.isfinite(mvol):
            mvol = 0.20
        recent_dd = 0.0
        if len(level) >= 20:
            peak = np.nanmax(level[-60:]) if len(level) >= 60 else np.nanmax(level)
            if np.isfinite(peak) and peak > 0:
                recent_dd = level[-1] / peak - 1.0
    else:
        mtrend = 0.0
        mvol = 0.20
        recent_dd = 0.0
    defensive = (mtrend < 0.0) or (mvol > 0.32) or (recent_dd < -0.08)
    if defensive:
        score = 0.35 * z_mom + 0.20 * z_high + 0.10 * z_trend + 0.35 * z_lowvol
    else:
        score = 0.45 * z_mom + 0.25 * z_high + 0.15 * z_trend + 0.15 * z_lowvol
    scale = 1.0
    if mtrend < 0.0:
        scale *= 0.75
    if mvol > 0.30:
        scale *= 0.85
    if mvol > 0.45:
        scale *= 0.80
    if recent_dd < -0.08:
        scale *= 0.80
    if recent_dd < -0.15:
        scale *= 0.75
    scale = float(np.clip(scale, 0.30, 1.0))
    m = min(50, len(idx) // 2)
    if m < 5:
        return zero
    order = np.argsort(score, kind='mergesort')
    long_sel = idx[order[-m:]]
    short_sel = idx[order[:m]]
    wt = min(0.02, 0.5 * scale / m)
    if wt <= 0.0 or not np.isfinite(wt):
        return zero
    w = np.zeros(n, dtype=float)
    w[long_sel] = wt
    w[short_sel] = -wt
    w = np.nan_to_num(w, nan=0.0, posinf=0.0, neginf=0.0)
    w = np.clip(w, -0.02, 0.02)
    return pd.Series(w, index=tickers)

import numpy as np
import pandas as pd
import math


def _get_df(history, names):
    for name in names:
        obj = history.get(name)
        if isinstance(obj, pd.DataFrame):
            return obj
    return None


def generate_weights(history, universe):
    universe = pd.Index(universe)
    if len(universe) == 0:
        return pd.Series(dtype=float)

    price = _get_df(history, ['adjusted_close', 'close'])
    if price is None:
        return pd.Series(0.0, index=universe)

    price = price.reindex(columns=universe).iloc[-260:]
    if price.shape[0] < 25:
        return pd.Series(0.0, index=universe)

    last = price.iloc[-1]
    cnt = price.notna().sum()
    valid = last.notna() & (last > 2.0) & (cnt >= 60)

    vol_df = _get_df(history, ['volume'])
    if vol_df is not None:
        vol_df = vol_df.reindex(columns=universe).iloc[-60:]
        vmed = vol_df.tail(20).median()
        valid = valid & (vmed > 100000)

    elig_df = _get_df(history, ['eligible'])
    if elig_df is not None:
        e = elig_df.reindex(columns=universe).iloc[-1]
        valid = valid & e.fillna(True).astype(bool)

    rets = price / price.shift(1) - 1.0
    vol = rets.tail(60).std()
    vol = vol.replace(0.0, np.nan).clip(lower=0.005)

    def form(k):
        if price.shape[0] >= k + 1:
            return price.iloc[-1] / price.iloc[-k - 1] - 1.0
        return pd.Series(np.nan, index=universe)

    ret21 = form(21)
    ret5 = form(5)

    valid = valid & ret21.notna() & (ret21 < 1.5) & (ret21 > -0.75)
    if valid.sum() < 4:
        return pd.Series(0.0, index=universe)

    m21 = ret21[valid].mean()
    m5 = ret5[valid].mean()
    z21 = (ret21 - m21) / (vol * math.sqrt(21.0))
    z5 = (ret5 - m5) / (vol * math.sqrt(5.0))

    score = -(0.8 * z21 + 0.2 * z5)
    score = score.where(valid).replace([np.inf, -np.inf], np.nan).dropna()

    if len(score) < 10:
        score = (-(0.8 * ret21 + 0.2 * ret5)).where(valid)
        score = score.replace([np.inf, -np.inf], np.nan).dropna()

    if len(score) < 2:
        return pd.Series(0.0, index=universe)

    m = len(score)
    n_side = min(50, m // 2)
    if n_side < 1:
        n_side = 1

    sorted_score = score.sort_values(ascending=False)
    long_names = sorted_score.index[:n_side]
    short_names = sorted_score.index[-n_side:]

    w = min(0.5 / n_side, 0.02)
    weights = pd.Series(0.0, index=universe)
    weights.loc[long_names] += w
    weights.loc[short_names] -= w

    net = weights.sum()
    if abs(net) > 1e-12:
        idx = weights.index[weights != 0.0]
        if len(idx) > 0:
            weights.loc[idx] -= net / len(idx)

    weights = weights.clip(-0.02, 0.02)
    gross = weights.abs().sum()
    if gross > 1.0:
        weights = weights * (1.0 / gross)

    return weights.fillna(0.0).astype(float)

import numpy as np
import pandas as pd
import math


def _get_df(history, names):
    for name in names:
        obj = history.get(name)
        if isinstance(obj, pd.DataFrame):
            return obj
    return None


def _zscore(s):
    s = s.replace([np.inf, -np.inf], np.nan)
    x = s.dropna()
    if len(x) < 2:
        return pd.Series(np.nan, index=s.index)
    mu = x.mean()
    sd = x.std(ddof=0)
    if not np.isfinite(sd) or sd < 1e-12:
        return pd.Series(0.0, index=s.index)
    return (s - mu) / sd


def generate_weights(history, universe):
    universe = pd.Index(universe)
    if len(universe) == 0:
        return pd.Series(dtype=float)

    price = _get_df(history, ['adjusted_close', 'close'])
    if price is None:
        return pd.Series(0.0, index=universe)

    price = price.reindex(columns=universe)
    if price.shape[0] < 160:
        return pd.Series(0.0, index=universe)

    idx = price.index
    last_date = idx[-1]
    days_since_monday = last_date.dayofweek
    asof_pos = price.shape[0] - 1 - days_since_monday
    if asof_pos < 150:
        asof_pos = price.shape[0] - 1

    p = price.iloc[:asof_pos + 1].tail(400)
    if p.shape[0] < 150:
        return pd.Series(0.0, index=universe)
    asof_date = p.index[-1]

    last = p.iloc[-1]
    cnt = p.notna().sum()
    valid = last.notna() & (last > 2.0) & (cnt >= 120)

    vol_df = _get_df(history, ['volume'])
    if vol_df is not None:
        vol_df = vol_df.reindex(index=idx, columns=universe).loc[:asof_date].tail(60)
        vmed = vol_df.tail(20).median()
        valid = valid & (vmed > 100000)

    elig_df = _get_df(history, ['eligible'])
    if elig_df is not None:
        elig_df = elig_df.reindex(index=idx, columns=universe).loc[:asof_date].tail(1)
        if elig_df.shape[0] > 0:
            e = elig_df.iloc[0]
            valid = valid & e.fillna(True).astype(bool)

    rets = p.pct_change()
    vol = rets.tail(60).std()
    vol = vol.replace([0.0, np.inf, -np.inf], np.nan).clip(lower=0.005)
    valid = valid & vol.notna()

    n = len(p)

    def form(k):
        if n >= k + 1:
            return p.iloc[-1] / p.iloc[-k - 1] - 1.0
        return pd.Series(np.nan, index=universe)

    ret126 = form(126)
    ret252 = form(252)

    valid = valid & ret126.notna() & (ret126 < 3.0) & (ret126 > -0.85)
    if valid.sum() < 4:
        return pd.Series(0.0, index=universe)

    z126 = ret126 / (vol * math.sqrt(126.0))
    z252 = ret252 / (vol * math.sqrt(252.0))
    z126s = _zscore(z126.where(valid))
    z252s = _zscore(z252.where(valid))

    if z252s.notna().sum() >= max(10, int(0.5 * valid.sum())):
        mom = 0.65 * z126s + 0.35 * z252s.fillna(0.0)
    else:
        mom = z126s

    volz = _zscore(vol.where(valid))
    score = 0.78 * mom - 0.22 * volz
    score = score.where(valid).replace([np.inf, -np.inf], np.nan).dropna()

    if len(score) < 10:
        alt = (ret126 / vol).where(valid)
        score = alt.replace([np.inf, -np.inf], np.nan).dropna()

    if len(score) < 2:
        return pd.Series(0.0, index=universe)

    m = len(score)
    n_side = min(50, m // 2)
    if n_side < 1:
        n_side = 1

    srt = score.sort_values(ascending=False)
    long_names = srt.index[:n_side]
    short_names = srt.index[-n_side:]

    w = min(0.5 / n_side, 0.02)
    weights = pd.Series(0.0, index=universe)
    weights.loc[long_names] += w
    weights.loc[short_names] -= w

    net = weights.sum()
    if abs(net) > 1e-12:
        active = weights.index[weights != 0.0]
        if len(active) > 0:
            weights.loc[active] -= net / len(active)

    weights = weights.clip(-0.02, 0.02)
    gross = weights.abs().sum()
    if gross > 1.0:
        weights = weights * (1.0 / gross)

    return weights.fillna(0.0).astype(float)
